#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=15

# ── This project's fixed facts ────────────────────────────────────────────
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
cd "$REPO_ROOT"
# Replaced in stage 1 by the name GitHub reports for this checkout's remote, which follows a rename.
GITHUB_REPO="vshpyrka/Tembra-Audio"
WORKFLOW_FILE=".github/workflows/play-closed-testing.yml"
PACKAGE_NAME="com.tembraaudio"
SA_NAME="play-publisher"
POOL_ID="github"
PROVIDER_ID="tembra-audio"
KEYSTORE_SECRET_NAME="play-upload-keystore"
PASSWORD_SECRET_NAME="play-upload-keystore-password"
# Values the wizard remembers between runs. None of them is secret: the upload key and its password only ever go to
# Secret Manager.
STATE_DIR="$HOME/.config/tembra-audio"
mkdir -p "$STATE_DIR"
chmod 700 "$STATE_DIR"
ENV_FILE="$STATE_DIR/play-setup.env"
KEY_DIR=""
trap 'if [[ -n "$KEY_DIR" ]]; then rm -rf "$KEY_DIR"; fi' EXIT

has_enabled_version() {
  [[ -n "$(gcloud secrets versions list "$1" --project="$GCP_PROJECT_ID" --filter='state=ENABLED' --limit=1 \
    --format='value(name)' 2>/dev/null || true)" ]]
}

# store_secret NAME FILE: a new secret, or a new version of one an interrupted run left behind.
store_secret() {
  if gcloud secrets describe "$1" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
    gcloud secrets versions add "$1" --project="$GCP_PROJECT_ID" --data-file="$2"
  else
    gcloud secrets create "$1" --project="$GCP_PROJECT_ID" --replication-policy=automatic \
      --labels=app=tembra-audio,purpose=play-upload-key --data-file="$2"
  fi
}

# inside_git_work_tree PATH: true when PATH, or its nearest existing parent, is in any git checkout.
inside_git_work_tree() {
  local dir="$1"
  while [[ ! -d "$dir" ]]; do dir=$(dirname "$dir"); done
  [[ "$(git -C "$dir" rev-parse --is-inside-work-tree 2>/dev/null || true)" == "true" ]]
}

billing_enabled() {
  local enabled
  enabled=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingEnabled)' 2>/dev/null || true)
  [[ "$(printf '%s' "$enabled" | tr '[:upper:]' '[:lower:]')" == "true" ]]
}

banner "Tembra Audio: Google Play closed testing setup"

# ──────────────────────────────────────────────────────────────────────────
stage "Tools on this Mac"
say "The wizard drives gcloud (Google Cloud), gh (GitHub) and the JDK's keytool."
missing=""
for tool in gcloud gh keytool openssl python3; do
  command -v "$tool" >/dev/null 2>&1 || missing="$missing $tool"
done
if [[ -n "$missing" ]]; then
  warn "missing:$missing"
  [[ "$missing" == *gcloud* ]] && step "Google Cloud CLI: brew install --cask gcloud-cli"
  [[ "$missing" == *" gh"* ]] && step "GitHub CLI: brew install gh, then gh auth login"
  [[ "$missing" == *keytool* ]] && step "keytool comes with any JDK, for example Android Studio's (Contents/jbr/Contents/Home/bin)"
  say "Install them, then run this wizard again."
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not signed in: run gh auth login, then this wizard again."
  exit 1
fi
GITHUB_REPO=$(gh api 'repos/{owner}/{repo}' --jq .full_name)
if [[ -z "$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null)" ]]; then
  say "Sign in to Google Cloud with the Google account that will own the project (a browser opens)."
  pause "Press Enter to run gcloud auth login"
  gcloud auth login
fi
note "GitHub: $(gh api user --jq .login) ($GITHUB_REPO)   Google Cloud: $(gcloud auth list --filter=status:ACTIVE --format='value(account)')"
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "Google Play Console developer account"
say "Skip this stage if you already have a verified Play Console developer account."
open_url "https://play.google.com/console/signup"
step "Sign in with the Google account that will own the app."
step "Pick the account type: Personal (you) or Organization (needs a D-U-N-S number)."
note "Personal accounts created after 13 Nov 2023 need 12 testers opted in for 14 days in a row before"
note "production access; closed testing, the only track this pipeline uses, works from day one."
step "Pay the one-time US\$25 fee and finish identity and contact verification (can take a few days)."
step "Turn on 2-Step Verification for the account: Google asks every Play Console user to."
open_url "https://myaccount.google.com/signinoptions/twosv"
pause "Press Enter once the developer account is verified"

# ──────────────────────────────────────────────────────────────────────────
stage "Create the app in Play Console"
open_url "https://play.google.com/console"
step "Home → Create app."
step "App name: Tembra Audio. Default language: English (United States) – en-US."
step "App or game: App. Free or paid: Free (a free app can never become paid)."
step "Accept the declarations (Developer Program Policies, US export laws), then Create app."
note "The package name is set by the first upload and can never change: $PACKAGE_NAME."
pause "Press Enter once the app exists"

# ──────────────────────────────────────────────────────────────────────────
stage "Google Cloud project"
say "One project holds the publishing service account, the keyless GitHub trust and the upload key."
say "Use a project for nothing else. IDs are global, for example tembra-audio-play-$(openssl rand -hex 2)."
ask GCP_PROJECT_ID "Project ID (an existing project, or a new ID to create):"
if gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Project $GCP_PROJECT_ID exists."
elif confirm "Create project $GCP_PROJECT_ID now?"; then
  gcloud projects create "$GCP_PROJECT_ID" --name="Tembra Audio Play"
else
  exit 1
fi
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
write_env GCP_PROJECT_NUMBER "$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')"
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "Billing account on the project"
say "Secret Manager, which keeps the upload key, only runs on a project with billing."
say "Two secret versions and a few reads per release sit inside the free tier: expect \$0 a month."
if billing_enabled; then
  say "Billing is already enabled on $GCP_PROJECT_ID."
else
  open_url "https://console.cloud.google.com/billing/linkedaccount?project=$GCP_PROJECT_ID"
  step "Link a billing account (create one if asked)."
  step "Optional: Billing → Budgets & alerts → a \$1 budget with an e-mail alert."
  pause "Press Enter once billing is linked"
  while ! billing_enabled; do
    confirm "Billing is not detected yet. Continue anyway?" && break
    pause "Press Enter to check again"
  done
fi
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "APIs and the publishing service account"
say "Enabling the APIs the pipeline calls (takes a minute)."
gcloud services enable androidpublisher.googleapis.com iam.googleapis.com iamcredentials.googleapis.com \
  sts.googleapis.com secretmanager.googleapis.com --project="$GCP_PROJECT_ID"
SA_EMAIL="$SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
if gcloud iam service-accounts describe "$SA_EMAIL" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Service account $SA_EMAIL exists."
else
  gcloud iam service-accounts create "$SA_NAME" --project="$GCP_PROJECT_ID" \
    --display-name="Google Play publisher (GitHub Actions)" \
    --description="Releases Tembra Audio to closed testing from $WORKFLOW_FILE on main. Never give it a key."
fi
write_env GCP_PLAY_SERVICE_ACCOUNT "$SA_EMAIL"
note "It gets no project role: only read access to the two upload-key secrets (stage 8) and, in"
note "Play Console, 'Release apps to testing tracks' (stage 10). Never create a JSON key for it."
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "Keyless trust: GitHub Actions → Google Cloud"
GITHUB_REPO_ID=$(gh api "repos/$GITHUB_REPO" --jq .id)
GITHUB_OWNER_ID=$(gh api "repos/$GITHUB_REPO" --jq .owner.id)
MAPPING="google.subject=assertion.sub,attribute.repository_id=assertion.repository_id,attribute.repository_owner_id=assertion.repository_owner_id,attribute.ref=assertion.ref,attribute.workflow_ref=assertion.workflow_ref"
CONDITION="assertion.repository_id == '$GITHUB_REPO_ID' && assertion.repository_owner_id == '$GITHUB_OWNER_ID' && assertion.ref == 'refs/heads/main' && assertion.workflow_ref == '$GITHUB_REPO/$WORKFLOW_FILE@refs/heads/main'"
say "Workload Identity Federation: Google Cloud accepts GitHub's OIDC token only when"
note "  repository id $GITHUB_REPO_ID, owner id $GITHUB_OWNER_ID (numeric, so a renamed or re-created"
note "  repository can't take over), branch main, workflow $WORKFLOW_FILE."
if ! gcloud iam workload-identity-pools describe "$POOL_ID" --project="$GCP_PROJECT_ID" --location=global >/dev/null 2>&1; then
  gcloud iam workload-identity-pools create "$POOL_ID" --project="$GCP_PROJECT_ID" --location=global \
    --display-name="GitHub Actions"
fi
if gcloud iam workload-identity-pools providers describe "$PROVIDER_ID" --project="$GCP_PROJECT_ID" --location=global \
    --workload-identity-pool="$POOL_ID" >/dev/null 2>&1; then
  gcloud iam workload-identity-pools providers update-oidc "$PROVIDER_ID" --project="$GCP_PROJECT_ID" \
    --location=global --workload-identity-pool="$POOL_ID" \
    --attribute-mapping="$MAPPING" --attribute-condition="$CONDITION"
else
  gcloud iam workload-identity-pools providers create-oidc "$PROVIDER_ID" --project="$GCP_PROJECT_ID" \
    --location=global --workload-identity-pool="$POOL_ID" --display-name="Tembra Audio main" \
    --issuer-uri="https://token.actions.githubusercontent.com" \
    --attribute-mapping="$MAPPING" --attribute-condition="$CONDITION"
fi
POOL_NAME=$(gcloud iam workload-identity-pools describe "$POOL_ID" --project="$GCP_PROJECT_ID" --location=global \
  --format='value(name)')
gcloud iam service-accounts add-iam-policy-binding "$SA_EMAIL" --project="$GCP_PROJECT_ID" \
  --role="roles/iam.workloadIdentityUser" \
  --member="principalSet://iam.googleapis.com/$POOL_NAME/attribute.repository_id/$GITHUB_REPO_ID" >/dev/null
write_env GCP_WORKLOAD_IDENTITY_PROVIDER "$POOL_NAME/providers/$PROVIDER_ID"
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "Upload key in Secret Manager"
say "Play App Signing keeps the app signing key at Google; you hold only an upload key, which Play"
say "can reset if it is ever lost or leaked. It lives in Secret Manager and nowhere else."
KEY_DIR=$(mktemp -d)
chmod 700 "$KEY_DIR"
if has_enabled_version "$KEYSTORE_SECRET_NAME" && has_enabled_version "$PASSWORD_SECRET_NAME"; then
  say "The upload key already exists; reading its certificate (the key stays in Secret Manager)."
  gcloud secrets versions access latest --secret="$KEYSTORE_SECRET_NAME" --project="$GCP_PROJECT_ID" \
    --out-file="$KEY_DIR/upload.p12"
  TEMBRA_UPLOAD_STOREPASS=$(gcloud secrets versions access latest --secret="$PASSWORD_SECRET_NAME" \
    --project="$GCP_PROJECT_ID")
  export TEMBRA_UPLOAD_STOREPASS
else
  if gcloud secrets describe "$KEYSTORE_SECRET_NAME" --project="$GCP_PROJECT_ID" >/dev/null 2>&1 \
      || gcloud secrets describe "$PASSWORD_SECRET_NAME" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
    warn "Secret Manager holds only part of an upload key: an earlier run stopped half-way."
    note "A new key replaces it. If Play Console already shows an upload key certificate for Tembra Audio,"
    note "stop here (Ctrl-C): a new key would then need an upload key reset (docs/google-play-publishing.md)."
  fi
  say "The wizard generates it now: RSA 4096 in a PKCS12 keystore, valid for 27 years, with a random"
  say "40-character password you never need to see."
  confirm "Generate the upload key and store it in Secret Manager?" || exit 1
  TEMBRA_UPLOAD_STOREPASS=$(openssl rand -base64 60 | tr -d '\n/+=' | cut -c1-40)
  export TEMBRA_UPLOAD_STOREPASS
  keytool -genkeypair -keystore "$KEY_DIR/upload.p12" -storetype PKCS12 -storepass:env TEMBRA_UPLOAD_STOREPASS \
    -alias upload -keyalg RSA -keysize 4096 -sigalg SHA256withRSA -validity 10000 \
    -dname "CN=Tembra Audio upload key, O=Tembra Audio"
  printf '%s' "$TEMBRA_UPLOAD_STOREPASS" > "$KEY_DIR/password"
  # The password first: a run that stops between the two leaves no keystore, so the next run starts over cleanly.
  store_secret "$PASSWORD_SECRET_NAME" "$KEY_DIR/password"
  store_secret "$KEYSTORE_SECRET_NAME" "$KEY_DIR/upload.p12"
fi
for secret in "$KEYSTORE_SECRET_NAME" "$PASSWORD_SECRET_NAME"; do
  gcloud secrets add-iam-policy-binding "$secret" --project="$GCP_PROJECT_ID" \
    --member="serviceAccount:$SA_EMAIL" --role="roles/secretmanager.secretAccessor" >/dev/null
done
UPLOAD_SHA256=$(keytool -list -v -keystore "$KEY_DIR/upload.p12" -storetype PKCS12 \
  -storepass:env TEMBRA_UPLOAD_STOREPASS -alias upload | awk '/SHA256: / && !found { sub(/^.*SHA256: /, ""); print; found = 1 }')
keytool -exportcert -rfc -keystore "$KEY_DIR/upload.p12" -storetype PKCS12 -storepass:env TEMBRA_UPLOAD_STOREPASS \
  -alias upload -file "$STATE_DIR/upload_certificate.pem" 2>/dev/null
say "Upload certificate SHA-256: $UPLOAD_SHA256"
note "Its public certificate is in $STATE_DIR/upload_certificate.pem (not secret)."
if confirm "Also save an offline backup of the keystore and password (for a password manager)?"; then
  while :; do
    ask BACKUP_DIR "Folder for the backup, outside any repository (for example ~/Desktop/tembra-key):"
    BACKUP_DIR="${BACKUP_DIR/#\~/$HOME}"
    if [[ "$BACKUP_DIR" != /* ]]; then
      warn "Give an absolute path, or one starting with ~."
    elif inside_git_work_tree "$BACKUP_DIR"; then
      warn "That folder is inside a git repository, where the key could be committed. Pick another."
    else
      break
    fi
  done
  mkdir -p "$BACKUP_DIR"
  (umask 077 && cp "$KEY_DIR/upload.p12" "$BACKUP_DIR/tembra-audio-upload.p12" \
    && printf '%s\n' "$TEMBRA_UPLOAD_STOREPASS" > "$BACKUP_DIR/tembra-audio-upload-password.txt")
  warn "Move both files into your password manager, then delete them from $BACKUP_DIR."
fi
rm -rf "$KEY_DIR"
KEY_DIR=""
unset TEMBRA_UPLOAD_STOREPASS
write_env PLAY_UPLOAD_CERT_SHA256 "$UPLOAD_SHA256"
write_env PLAY_UPLOAD_KEYSTORE_SECRET "projects/$GCP_PROJECT_ID/secrets/$KEYSTORE_SECRET_NAME"
write_env PLAY_UPLOAD_PASSWORD_SECRET "projects/$GCP_PROJECT_ID/secrets/$PASSWORD_SECRET_NAME"
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub repository variables"
say "The workflow reads these. None is a secret: they only name resources, and Google Cloud lets"
say "nothing but $WORKFLOW_FILE on main use them."
set_var GCP_WORKLOAD_IDENTITY_PROVIDER "$GCP_WORKLOAD_IDENTITY_PROVIDER"
set_var GCP_PLAY_SERVICE_ACCOUNT "$GCP_PLAY_SERVICE_ACCOUNT"
set_var PLAY_UPLOAD_KEYSTORE_SECRET "$PLAY_UPLOAD_KEYSTORE_SECRET"
set_var PLAY_UPLOAD_PASSWORD_SECRET "$PLAY_UPLOAD_PASSWORD_SECRET"
set_var PLAY_UPLOAD_CERT_SHA256 "$PLAY_UPLOAD_CERT_SHA256"
if [[ -n "$(gh variable get PLAY_TRACK 2>/dev/null || true)" ]]; then
  note "PLAY_TRACK stays $(gh variable get PLAY_TRACK)."
else
  set_var PLAY_TRACK "alpha"
fi
note "From now on the workflow's publish job runs. Optional variables: PLAY_RELEASE_STATUS (completed or"
note "draft) and PLAY_NOTES_LANGUAGE (en-US). Deleting GCP_PLAY_SERVICE_ACCOUNT pauses publishing."
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "Play Console: let the service account release to testing"
open_url "https://play.google.com/console"
step "Left menu: Users and permissions → Invite new users."
step "Email address: $GCP_PLAY_SERVICE_ACCOUNT"
step "Account permissions: leave every box empty."
step "App permissions → Add app → Tembra Audio → Apply."
step "Tick only 'Release apps to testing tracks' (Play adds read-only app access with it) → Apply."
step "Invite user. A service account is active at once; there is no e-mail to accept."
note "Without production or store-listing rights, even a leaked token could not reach production users."
pause "Press Enter once the service account is listed"

# ──────────────────────────────────────────────────────────────────────────
stage "Play Console: App content declarations"
open_url "https://play.google.com/console"
step "Tembra Audio → Policy and programs → App content (or the Dashboard's 'Set up your app' list)."
step "Privacy policy: a public URL. The app records from the microphone, so Play requires one."
step "App access: all functionality is available without special access (no sign-in)."
step "Ads: No. Content rating: fill in the IARC questionnaire (a music utility, no user content)."
step "Target audience: the ages you aim at; choosing under 13 brings the Families policy."
step "Data safety: the app has no internet permission and keeps audio and projects on the device;"
say  "  declare what applies (likely 'no data collected or shared') and keep it true as features land."
step "Government apps, financial features, health apps, news: No / none."
step "Foreground service permissions: media playback (metronome and transport with the screen off),"
say  "  and microphone once recording (feature 010) ships. Each needs a short video link, e.g. unlisted YouTube."
pause "Press Enter once every declaration shows as complete"

# ──────────────────────────────────────────────────────────────────────────
stage "Play Console: Main store listing"
open_url "https://play.google.com/console"
step "Grow users → Store presence → Main store listing."
step "App name (30 chars), short description (80), full description (4000)."
step "App icon 512×512 PNG, feature graphic 1024×500, at least 2 phone screenshots,"
say  "  plus 7-inch and 10-inch tablet screenshots (the app supports tablets)."
step "Store settings: category Music & Audio, contact e-mail. Save."
note "Closed testers see this listing, so it must be complete before the first rollout."
pause "Press Enter once the listing is saved"

# ──────────────────────────────────────────────────────────────────────────
stage "Play Console: closed testing track and testers"
open_url "https://play.google.com/console"
step "Test and release → Testing → Closed testing → the default track 'Alpha' → Manage track."
step "Testers → Create email list (for example 'Tembra testers'), add your own address and the testers', Save."
step "Countries / regions → add where testers live."
step "Feedback URL or e-mail for testers. Save."
note "The API calls this track 'alpha' (PLAY_TRACK). For a custom closed track, set PLAY_TRACK to its name;"
note "the workflow refuses 'beta' (open testing) and 'production'."
pause "Press Enter once the track has testers"

# ──────────────────────────────────────────────────────────────────────────
stage "First signed bundle from GitHub Actions"
say "Google needs the very first bundle uploaded by hand. The workflow builds, tests and signs it."
if ! gh api "repos/$GITHUB_REPO/contents/$WORKFLOW_FILE?ref=main" >/dev/null 2>&1; then
  warn "$WORKFLOW_FILE is not on main yet: merge the pull request that adds it, then run this wizard again."
  exit 1
fi
FIRST_UPLOAD_DIR="$HOME/Downloads/tembra-audio-first-upload"
FIRST_BUNDLE=$(_existing FIRST_BUNDLE || true)
if [[ -n "$FIRST_BUNDLE" && -f "$FIRST_BUNDLE" ]] && confirm "Reuse $FIRST_BUNDLE from an earlier run?"; then
  say "Reusing $FIRST_BUNDLE."
else
previous=$(gh run list --repo "$GITHUB_REPO" --workflow play-closed-testing.yml --event workflow_dispatch --limit 1 \
  --json databaseId --jq '.[0].databaseId // ""')
gh workflow run play-closed-testing.yml --repo "$GITHUB_REPO" --ref main -f publish=false
run=""
for _ in $(seq 1 30); do
  sleep 4
  run=$(gh run list --repo "$GITHUB_REPO" --workflow play-closed-testing.yml --event workflow_dispatch --limit 1 \
    --json databaseId --jq '.[0].databaseId // ""')
  [[ -n "$run" && "$run" != "$previous" ]] && break
done
say "Run $run: https://github.com/$GITHUB_REPO/actions/runs/$run (about 20 minutes)"
if ! gh run watch "$run" --repo "$GITHUB_REPO" --exit-status; then
  warn "The run failed. Read it with: gh run view $run --repo $GITHUB_REPO --log-failed"
  exit 1
fi
rm -rf "$FIRST_UPLOAD_DIR"
gh run download "$run" --repo "$GITHUB_REPO" --name signed-bundle --dir "$FIRST_UPLOAD_DIR"
write_env FIRST_BUNDLE "$FIRST_UPLOAD_DIR/tembra-audio.aab"
fi
pause "Press Enter to continue"

# ──────────────────────────────────────────────────────────────────────────
stage "First release by hand, then automatic"
open_url "https://play.google.com/console"
step "Test and release → Testing → Closed testing → Alpha → Create new release."
step "Play app signing: keep 'Google-generated key' (the default). Do not choose your own key."
step "App bundles → Upload: $FIRST_BUNDLE"
step "Release notes: paste $FIRST_UPLOAD_DIR/release-notes.txt. Next → Save → Send changes for review."
step "Then: Test and release → App integrity → Play app signing → Upload key certificate."
say  "  Its SHA-256 must be: $PLAY_UPLOAD_CERT_SHA256"
step "Share the testers' opt-in link: Closed testing → Alpha → Testers → 'Join on the web'."
note "After this, every merge to main that changes the app goes to review and then to the testers."
note "Release main by hand at any time: gh workflow run play-closed-testing.yml -f publish=true"
pause "Press Enter when the first release is sent for review"

finish
}

run_wizard "$@"; exit
